// scripts/build-bundle.js
// Rebuilds _ds_bundle.js from all component sources in a single pass.
// Replaces extend-bundle.js — run: node scripts/build-bundle.js
import { transformSync } from 'esbuild';
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const __dir = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dir, '..');

const COMPONENTS = [
  'Accordion', 'ArrowLink', 'Badge', 'Breadcrumb', 'Button',
  'Checkbox', 'CheckboxGroup', 'FormField', 'Input', 'Logo',
  'MediaCard', 'Modal', 'NavigationBar', 'Radio', 'RadioGroup',
  'SectionHeader', 'Select', 'SocialLink', 'Stat', 'Tag',
  'Tabs', 'Textarea', 'Toast',
];

function transformComponent(name) {
  const src = readFileSync(join(ROOT, `components/core/${name}.jsx`), 'utf8');
  const cleaned = src
    .replace(/^import\s+React\s+from\s+['"]react['"];?\s*\n?/gm, '')
    .replace(/^export\s+(?=function|const|class)/gm, '');
  return transformSync(cleaned, {
    loader: 'jsx',
    jsxFactory: 'React.createElement',
    jsxFragment: 'React.Fragment',
  }).code.trim();
}

const blocks = COMPONENTS.map((name) => {
  const code = transformComponent(name);
  return (
    `// components/core/${name}.jsx\n` +
    `try { (() => {\n${code}\n  __ds_scope.${name} = ${name};\n` +
    `})(); } catch (e) { __ds_ns.__errors.push({ name: "${name}", error: String((e && e.message) || e) }); }`
  );
});

const exportLines = COMPONENTS.map((n) => `__ds_ns.${n} = __ds_scope.${n};`).join('\n');

const bundle = [
  `// TEDxAmsterdam Design System — browser bundle`,
  `// Generated by scripts/build-bundle.js — do not edit manually.`,
  `// Components: ${COMPONENTS.join(', ')}`,
  `(function () {`,
  `  'use strict';`,
  `  var __ds_scope = {};`,
  `  var __ds_ns = window.TEDxAmsterdamDesignSystem = window.TEDxAmsterdamDesignSystem || {};`,
  `  __ds_ns.__errors = [];`,
  ``,
  blocks.join('\n\n'),
  ``,
  exportLines,
  `})();`,
].join('\n');

writeFileSync(join(ROOT, '_ds_bundle.js'), bundle);
console.log(`\u2713 Bundle rebuilt: ${COMPONENTS.length} components`);
